from pathlib import Path
import re
root=Path('dist'); old=Path('scripts/home-template.html').read_text()
services=[
('production','Production','THE IDEA.\nTHE SET.\nTHE EXECUTION.','A considered production journey, from planning the shoot to capturing the final take.',['Shoot planning & scheduling','Crew & equipment coordination','Location & set planning','On-set production'],['Define the brief','Build the production plan','Bring the shoot to life']),
('film','Film','STORIES MADE\nFOR THE SCREEN.','Films shaped by a clear point of view. From the first treatment to the atmosphere of the final frame.',['Story & concept development','Visual treatment & direction','Short films & narrative projects','Cinematography planning'],['Find the story','Shape the visual language','Capture the narrative']),
('editing','Editing','FIND THE RHYTHM.\nFEEL THE STORY.','Turn captured moments into a coherent story through pacing, colour, sound and carefully considered finishing.',['Offline & online editing','Colour correction & grading','Sound & music coordination','Platform-ready exports'],['Review the footage','Build and refine the cut','Finish and deliver']),
('brand-shoot','Brand Shoot','YOUR BRAND.\nIN ITS BEST LIGHT.','Purposeful brand imagery that connects the product, the people and the story behind it.',['Product & campaign shoots','Brand films & commercials','Lifestyle & visual storytelling','Social-first shoot formats'],['Understand the brand','Develop the shoot concept','Create the campaign assets']),
('marketing','Marketing','MAKE IT SEEN.\nMAKE IT MATTER.','Connect creative content with a clear campaign direction, an audience and a practical distribution plan.',['Campaign concept & planning','Social content direction','Content calendars & launch assets','Campaign review & optimisation'],['Set the objective','Build the content plan','Launch, learn and refine']),
('film-investment','Film Investment','BACK THE STORY.\nBUILD THE VISION.','Start a conversation about a film project, its creative direction, production plan and potential funding partnership.',['Project & pitch discussion','Budget & production-plan review','Funding structure discussion','Milestones & project updates'],['Share the project','Review scope and budget','Discuss a potential partnership'])]
header='''<header><a class="brand" href="index.html" aria-label="Panther Productions home"><img src="assets/logo.png" alt="Panther Productions"></a><nav aria-label="Main navigation"><a href="index.html">Home</a><a href="work.html">Work</a><a href="studio.html">Studio</a><a href="services.html">Services</a></nav><a class="talk" href="contact.html">Let's talk <span>↗</span></a></header>'''
footer='''<footer><a href="index.html">PANTHER <small>PRODUCTIONS</small></a><div class="footer-links"><a href="work.html">Work</a><a href="studio.html">Studio</a><a href="services.html">Services</a><a href="contact.html">Contact</a></div><span>© <span id="year"></span> Panther Productions</span></footer><dialog id="dialog"><button class="close" aria-label="Close preview">CLOSE ✕</button><div id="dialog-body"></div></dialog><script src="app.js"></script>'''
def doc(title,content,home=False):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Panther Productions — '+title+'. Film, production and post."><title>'+title+' — Panther Productions</title><link rel="stylesheet" href="style.css"></head><body class="'+('home-page' if home else 'inner-page')+'">'+header+'<main>'+content+'</main>'+footer+'</body></html>'
def section(id):return re.search(r'<section\b[^>]*\bid="'+id+r'"[^>]*>.*?</section>',old,re.S).group()
def lead(k,title,desc):return '<section class="page-lead"><a class="crumb" href="index.html">PANTHER / '+k.upper()+'</a><div class="eyebrow">'+k+'</div><h1>'+title+'</h1><p>'+desc+'</p></section>'
def cta(text='HAVE A STORY IN MIND?'):return '<section class="page-cta"><span class="eyebrow">THE NEXT FRAME IS YOURS</span><h2>'+text+'</h2><a class="contact-button" href="contact.html">Start a conversation ↗</a></section>'
def service_grid():
 return '<div class="service-grid">'+''.join('<a class="service-tile" href="service-'+slug+'.html"><span class="service-number">0'+str(i+1)+' /</span><h3>'+name+'<b>↗</b></h3><p>'+desc+'</p><span class="service-explore">EXPLORE SERVICE</span></a>' for i,(slug,name,head,desc,inc,flow) in enumerate(services))+'</div>'
hero=section('home').replace('href="#work"','href="work.html"')
work=section('work'); studio=section('studio').replace('href="#contact"','href="contact.html"')
contact=section('contact').replace('<option>Brand film</option><option>Film production</option><option>Editing & post</option><option>Something different</option>',''.join('<option>'+x[1]+'</option>' for x in services)+'<option>Something different</option>')
homework=work.replace('SELECTED<br><em>VISUAL WORLDS.</em>','A GLIMPSE<br><em>OF THE INSTINCT.</em>')
home=hero+'<div class="ticker" aria-hidden="true"><div>PRODUCTION <i>✦</i> FILM <i>✦</i> EDITING <i>✦</i> BRAND SHOOT <i>✦</i> MARKETING <i>✦</i> FILM INVESTMENT <i>✦</i></div></div>'+homework+'<section class="section home-services"><div class="section-head"><span class="eyebrow">WHAT WE DO</span><h2>ONE VISION.<br><em>SIX WAYS IN.</em></h2><p>Explore the craft behind the frame.</p></div>'+service_grid()+'</section>'+cta()
(root/'index.html').write_text(doc('Stories with a wild side',home,True))
(root/'work.html').write_text(doc('Work',lead('01 / Work','VISUAL<br>WORLDS<span>.</span>','Explore our cinematic direction through a collection of illustrative concept studies.')+work+cta()))
(root/'studio.html').write_text(doc('Studio',lead('02 / Studio','THE INSTINCT<br>BEHIND THE FRAME<span>.</span>','Panther Productions. A creative journey from the first idea to the final frame.')+studio+'<section class="section philosophy"><span class="eyebrow">HOW WE APPROACH A STORY</span><div><h2>IDEA. CRAFT.<br><em>INTENTION.</em></h2><p>A clear idea guides the work. Careful preparation gives the shoot its focus. Editing brings everything into rhythm. We see these as parts of one creative journey.</p><a class="text-link" href="services.html">Explore our services ↗</a></div></section>'+cta()))
(root/'services.html').write_text(doc('Services',lead('03 / Services','THE CREATIVE<br>ARSENAL<span>.</span>','Six disciplines. One continuous creative journey. Choose where your story begins.')+'<section class="section services-overview">'+service_grid()+'</section>'+cta()))
(root/'contact.html').write_text(doc('Contact',lead('04 / Contact','YOUR NEXT<br>FRAME STARTS HERE<span>.</span>','Tell us what you are planning. Build a project brief to share with the studio.')+contact))
for i,(slug,name,headline,desc,includes,flow) in enumerate(services):
 content=lead('Service / '+name,headline.rstrip('.').replace('\n','<br>')+'<span>.</span>',desc)
 content+='<section class="service-feature"><img src="assets/'+('desert.jpg' if slug in ['film','brand-shoot','film-investment'] else 'set.jpg')+'" alt="'+name+' cinematic concept"><div><span class="eyebrow">0'+str(i+1)+' / '+name.upper()+'</span><h2>THE SCOPE.</h2><ul>'+''.join('<li>'+t+'</li>' for t in includes)+'</ul><a class="contact-button" href="contact.html?service='+slug+'">Discuss '+name+' ↗</a></div></section>'
 content+='<section class="section"><div class="section-head"><span class="eyebrow">THE APPROACH</span><h2>FROM FIRST<br><em>CONVERSATION.</em></h2></div><div class="process-grid">'+''.join('<div><span>0'+str(n+1)+'</span><h3>'+t+'</h3></div>' for n,t in enumerate(flow))+'</div>'
 if slug=='film-investment':content+='<p class="investment-note">Project enquiries only. Funding availability, participation terms and project risks are discussed individually. This page does not offer an investment or promise returns.</p>'
 content+='</section><section class="related-service"><span>EXPLORE NEXT</span><a href="service-'+services[(i+1)%len(services)][0]+'.html">'+services[(i+1)%len(services)][1]+' ↗</a></section>'+cta('LET’S TALK '+('FILM.' if slug=='film-investment' else 'POSSIBILITIES.'))
 (root/('service-'+slug+'.html')).write_text(doc(name,content))
